                    colorProp1: new Color3(0.1, 0.2, 0.3),
                    stringProp1: "hello world",
                    optionsProp1: 2,
                    tabProp1: "Tab1",
                    vector2Prop1: new Vector2(4, 5),
                    inspectableCustomProperties: [
